148: function movePlayer(dt) {
149:   const left = keys.has('ArrowLeft') || keys.has('a') || touchDirs.has('left');
150:   const right = keys.has('ArrowRight') || keys.has('d') || touchDirs.has('right');
151:   const jumpHeld = keys.has('ArrowUp') || keys.has('w') || keys.has(' ') || touchDirs.has('up') || touchDirs.has('jump');
152:   const direction = Number(right) - Number(left);
153:   if (direction) {
154:     player.vx += direction * 1500 * dt;
155:     player.facing = direction;
156:   } else {
157:     player.vx *= Math.pow(0.0008, dt);
158:   }
159:   player.vx = clamp(player.vx, -285, 285);
160:   if (jumpQueued) player.jumpBuffer = 0.13;
161:   else player.jumpBuffer = Math.max(0, player.jumpBuffer - dt);
162:   if (player.grounded) player.coyote = 0.12;
163:   else player.coyote = Math.max(0, player.coyote - dt);
164:   if (player.jumpBuffer > 0 && player.coyote > 0) {
165:     player.vy = -570;
166:     player.grounded = false;
167:     player.coyote = 0;
168:     player.jumpBuffer = 0;
169:   }
170:   if (!jumpHeld && player.vy < -180) player.vy += 1200 * dt;
171:   jumpQueued = false;
172:   player.vy = Math.min(player.vy + 1550 * dt, 760);
173: 
174:   const oldX = player.x;
175:   const oldY = player.y;
176:   const wasGrounded = player.grounded;
177:   player.x += player.vx * dt;
178:   player.x = clamp(player.x, 0, LEVEL_WIDTH - player.w);
179: 
180:   for (const pipe of PIPES) {
181:     const overlapsVertically = player.y < pipe.y + pipe.h && player.y + player.h > pipe.y;
182:     if (overlapsVertically && player.x + player.w > pipe.x && player.x < pipe.x + pipe.w) {
183:       if (player.vx > 0) player.x = pipe.x - player.w;
184:       else if (player.vx < 0) player.x = pipe.x + pipe.w;
185:       player.vx = 0;
186:     }
187:   }
188: 
189:   player.y += player.vy * dt;
190:   player.grounded = false;
191: 
192:   if (player.vy >= 0) {
193:     for (const p of [...platforms, ...PIPES]) {
194:       const crossedTop = oldY + player.h <= p.y + 2 && player.y + player.h >= p.y;
195:       if (crossedTop && player.x + player.w > p.x && player.x < p.x + p.w) {
196:         player.y = p.y - player.h;
197:         player.vy = 0;
198:         player.grounded = true;
199:       }
200:     }
201:   } else {
202:     for (const pipe of PIPES) {
203:       const pipeBottom = pipe.y + pipe.h;
204:       const hitUnderside = oldY >= pipeBottom - 2 && player.y <= pipeBottom;
205:       if (hitUnderside && player.x + player.w > pipe.x && player.x < pipe.x + pipe.w) {
206:         player.y = pipeBottom;
207:         player.vy = 0;
208:       }
209:     }
210:   }
211:   if (!wasGrounded && player.grounded) burst(player.x + player.w / 2, player.y + player.h, '#fff4d2', 4);
212:   if (player.grounded && Math.abs(player.vx) > 18) {
213:     player.walk += dt * (5.5 + Math.abs(player.vx) * 0.025);
214:   }
215:   if (player.y > H + 100) loseLife(true);
216:   if (player.invulnerable > 0) player.invulnerable = Math.max(0, player.invulnerable - dt);
217: }
