219: function update(dt) {
220:   elapsed += dt;
221:   movePlayer(dt);
222:   cameraX = clamp(player.x - W * 0.36, 0, LEVEL_WIDTH - W);
223:   if (!player.checkpointActive && player.x + player.w >= CHECKPOINT_X) {
224:     player.checkpoint = CHECKPOINT_X + 18;
225:     player.checkpointActive = true;
226:     setMessage('Checkpoint reached!');
227:     burst(CHECKPOINT_X, GROUND_Y - 36, '#8fffc1', 12);
228:   }
229: 
230:   for (const coin of coins) {
231:     if (!coin.taken) {
232:       const bobY = coin.y + Math.sin(elapsed * 5 + coin.phase) * 4;
233:       const box = { x: coin.x - 12, y: bobY - 14, w: 24, h: 28 };
234:       if (overlap(player, box)) {
235:         coin.taken = true;
236:         player.coins += 1;
237:         burst(coin.x, bobY, '#ffd84e', 7);
238:         updateHUD();
239:       }
240:     }
241:   }
242: 
243:   for (const enemy of enemies) {
244:     if (!enemy.alive) {
245:       enemy.squishTimer = Math.max(0, enemy.squishTimer - dt);
246:       continue;
247:     }
248:     enemy.x += enemy.dir * enemy.speed * dt;
249:     if (enemy.x < enemy.min || enemy.x + enemy.w > enemy.max) enemy.dir *= -1;
250:     if (overlap(player, enemy)) {
251:       const stomp = player.vy > 80 && player.y + player.h - enemy.y < 20;
252:       if (stomp) {
253:         enemy.alive = false;
254:         enemy.squishTimer = ENEMY_SQUISH_DURATION;
255:         player.vy = -360;
256:         cameraShake = Math.max(cameraShake, 3);
257:         burst(enemy.x + enemy.w / 2, enemy.y, '#c58a53', 10);
258:       } else {
259:         loseLife();
260:       }
261:     }
262:   }
263: 
264:   if (player.x + player.w >= GOAL_X) {
265:     if (player.coins >= TARGET_COINS) {
266:       gameState = 'won';
267:       showOverlay('You made it!', `Amazing run! You grabbed ${player.coins} coins and reached the flag.`, 'Play Again');
268:     } else {
269:       setMessage(`Find ${TARGET_COINS - player.coins} more coins to unlock the flag!`);
270:       player.x = GOAL_X - player.w - 2;
271:       player.vx = 0;
272:     }
273:   }
274:   if (messageTimer > 0) messageTimer -= dt;
275:   particles = particles.filter(p => p.life > 0);
276:   for (const p of particles) {
277:     p.life -= dt;
278:     p.x += p.vx * dt;
279:     p.y += p.vy * dt;
280:     p.vy += 300 * dt;
281:   }
282: }
