301: function drawBackground() {
302:   const sky = ctx.createLinearGradient(0, 0, 0, H);
303:   sky.addColorStop(0, '#3988d9');
304:   sky.addColorStop(0.38, '#72c7f1');
305:   sky.addColorStop(0.76, '#c7eff0');
306:   sky.addColorStop(1, '#f5f5ce');
307:   ctx.fillStyle = sky;
308:   ctx.fillRect(0, 0, W, H);
309: 
310:   // Warm sun glow and a slow, subtle atmospheric pulse.
311:   const sunX = 755 - cameraX * 0.035;
312:   const sunY = 102;
313:   const sunGlow = ctx.createRadialGradient(sunX, sunY, 8, sunX, sunY, 190);
314:   sunGlow.addColorStop(0, 'rgba(255,246,190,0.76)');
315:   sunGlow.addColorStop(0.28, 'rgba(255,238,172,0.26)');
316:   sunGlow.addColorStop(1, 'rgba(255,238,172,0)');
317:   ctx.fillStyle = sunGlow;
318:   ctx.fillRect(sunX - 190, sunY - 190, 380, 380);
319:   ctx.fillStyle = '#fff4bd';
320:   ctx.beginPath();
321:   ctx.arc(sunX, sunY, 25, 0, Math.PI * 2);
322:   ctx.fill();
323:   ctx.fillStyle = 'rgba(255,255,255,0.58)';
324:   ctx.beginPath();
325:   ctx.ellipse(sunX - 6, sunY - 8, 10, 4, -0.5, 0, Math.PI * 2);
326:   ctx.fill();
327: 
328:   // Distant mountain silhouettes create scale behind the playable valley.
329:   const mountainLayers = [
330:     { spacing: 420, parallax: 0.12, base: 377, color: '#91c9d4', peak: 100 },
331:     { spacing: 520, parallax: 0.2, base: 398, color: '#72b6ba', peak: 77 },
332:   ];
333:   for (const layer of mountainLayers) {
334:     const drift = (cameraX * layer.parallax) % layer.spacing;
335:     for (let i = -2; i < 5; i += 1) {
336:       const x = i * layer.spacing - drift;
337:       const peakX = x + layer.spacing * (0.36 + (i % 2) * 0.12);
338:       const peakY = layer.base - layer.peak;
339:       ctx.fillStyle = layer.color;
340:       ctx.beginPath();
341:       ctx.moveTo(x - 20, layer.base);
342:       ctx.lineTo(peakX, peakY);
343:       ctx.lineTo(x + layer.spacing * 0.68, layer.base);
344:       ctx.closePath();
345:       ctx.fill();
346:       ctx.fillStyle = 'rgba(248,255,239,0.78)';
347:       ctx.beginPath();
348:       ctx.moveTo(peakX, peakY);
349:       ctx.lineTo(peakX - 27, peakY + 36);
350:       ctx.lineTo(peakX - 5, peakY + 28);
351:       ctx.lineTo(peakX + 15, peakY + 43);
352:       ctx.closePath();
353:       ctx.fill();
354:     }
355:   }
356: 
357:   // Rolling hills at two parallax speeds soften the mountain horizon.
358:   for (let layer = 0; layer < 2; layer += 1) {
359:     const spacing = layer ? 280 : 360;
360:     const drift = (cameraX * (layer ? 0.34 : 0.25)) % spacing;
361:     ctx.fillStyle = layer ? '#8bd28c' : '#a9df9c';
362:     ctx.beginPath();
363:     ctx.moveTo(-spacing, 444);
364:     for (let i = -2; i < 7; i += 1) {
365:       const x = i * spacing - drift;
366:       const peak = 365 + ((i + layer) % 3) * 17;
367:       ctx.quadraticCurveTo(x + spacing * 0.48, peak, x + spacing, 435);
368:     }
369:     ctx.lineTo(W + spacing, H);
370:     ctx.lineTo(-spacing, H);
371:     ctx.closePath();
372:     ctx.fill();
373:   }
374: 
375:   // Sunlit clouds float at different depths.
376:   for (let i = 0; i < 8; i += 1) {
377:     const x = i * 175 - (cameraX * 0.16 % 175) - 55;
378:     const y = 72 + (i % 3) * 47;
379:     drawCloud(x, y, 0.78 + (i % 2) * 0.2);
380:   }
381: 
382:   // A soft tree line anchors the playable space without competing with it.
383:   for (let i = 0; i < 16; i += 1) {
384:     const spacing = 125;
385:     const x = i * spacing - (cameraX * 0.62 % spacing) - 30;
386:     const height = 28 + (i % 4) * 8;
387:     const crownY = 416 - height;
388:     ctx.fillStyle = 'rgba(92,75,60,0.72)';
389:     ctx.fillRect(x - 3, crownY + 20, 7, 40);
390:     const crown = ctx.createLinearGradient(0, crownY, 0, crownY + 46);
391:     crown.addColorStop(0, i % 2 ? '#4eae6a' : '#55b773');
392:     crown.addColorStop(1, '#32885c');
393:     ctx.fillStyle = crown;
394:     ctx.beginPath();
395:     ctx.arc(x, crownY + 12, 22, Math.PI, 0);
396:     ctx.arc(x + 17, crownY + 25, 17, Math.PI * 1.05, Math.PI * 0.05);
397:     ctx.arc(x - 17, crownY + 27, 17, Math.PI * 0.95, -0.05);
398:     ctx.closePath();
399:     ctx.fill();
400:     ctx.fillStyle = 'rgba(207,255,174,0.25)';
401:     ctx.beginPath();
402:     ctx.arc(x - 7, crownY + 8, 7, Math.PI, 0);
403:     ctx.fill();
404:   }
405: 
406:   // Tiny drifting pollen catches the light and adds a sense of air and depth.
407:   for (let i = 0; i < 18; i += 1) {
408:     const drift = (elapsed * (7 + i % 4) + i * 73) % (W + 20);
409:     const x = (drift - cameraX * 0.08 + W) % W;
410:     const y = 190 + (i * 47 % 220) + Math.sin(elapsed * 1.3 + i) * 5;
411:     ctx.fillStyle = `rgba(255,250,195,${0.22 + (i % 3) * 0.1})`;
412:     ctx.beginPath();
413:     ctx.arc(x, y, i % 4 === 0 ? 1.8 : 1.1, 0, Math.PI * 2);
414:     ctx.fill();
415:   }
416: }
