418: function drawCloud(x, y, s) {
419:   ctx.save();
420:   ctx.translate(0, Math.sin(elapsed * 0.5 + x * 0.01) * 2);
421:   ctx.fillStyle = 'rgba(89,151,188,0.18)';
422:   ctx.beginPath();
423:   ctx.ellipse(x + 44 * s, y + 25 * s, 43 * s, 12 * s, 0, 0, Math.PI * 2);
424:   ctx.fill();
425:   const cloud = ctx.createLinearGradient(0, y, 0, y + 28 * s);
426:   cloud.addColorStop(0, 'rgba(255,255,255,0.98)');
427:   cloud.addColorStop(0.65, 'rgba(250,253,248,0.94)');
428:   cloud.addColorStop(1, 'rgba(214,237,240,0.9)');
429:   ctx.fillStyle = cloud;
430:   ctx.beginPath();
431:   ctx.arc(x + 22 * s, y + 16 * s, 17 * s, Math.PI, 0);
432:   ctx.arc(x + 43 * s, y + 10 * s, 23 * s, Math.PI, 0);
433:   ctx.arc(x + 68 * s, y + 18 * s, 16 * s, Math.PI, 0);
434:   ctx.lineTo(x + 84 * s, y + 22 * s);
435:   ctx.lineTo(x + 7 * s, y + 22 * s);
436:   ctx.closePath();
437:   ctx.fill();
438:   ctx.restore();
439: }
