469:       ctx.fillStyle = 'rgba(255,190,115,0.16)';
470:       ctx.fillRect(x, p.y + 24, p.w, 2);
471:       ctx.fillRect(x, p.y + 61, p.w, 1);
472:       ctx.fillStyle = 'rgba(74,38,34,0.48)';
473:       for (let bx = p.x + 12; bx < p.x + p.w; bx += 44) {
474:         const sx = bx - cameraX;
475:         ctx.fillRect(sx, p.y + 34, 3, 25);
476:         ctx.fillRect(sx + 20, p.y + 69, 3, 24);
