529:     ctx.fillRect(x, y, pipe.w, 16);
530:     ctx.fillStyle = 'rgba(255,255,255,0.5)';
531:     ctx.fillRect(x + 4, y + 2, pipe.w - 8, 2);
532:     ctx.fillStyle = 'rgba(0,74,35,0.42)';
