536:   const cx = CHECKPOINT_X - cameraX;
537:   const flagSwing = Math.sin(elapsed * 4) * 4;
538:   ctx.fillStyle = '#f4f0dc';
539:   ctx.fillRect(cx, 382, 6, GROUND_Y - 382);
540:   ctx.fillStyle = player && player.checkpointActive ? '#35d99a' : '#f1a94e';
541:   ctx.beginPath();
