614: function drawEnemy(enemy) {
615:   if (!enemy.alive && enemy.squishTimer <= 0) return;
616:   const x = enemy.x - cameraX;
617:   const squishProgress = enemy.alive ? 0 : 1 - enemy.squishTimer / ENEMY_SQUISH_DURATION;
618:   const squashIn = clamp(squishProgress / 0.16, 0, 1);
619:   const squeeze = 1 - Math.pow(1 - squashIn, 3);
620:   const scaleY = 1 - squeeze * 0.68;
621:   const scaleX = 1 + squeeze * 0.38;
622:   const fade = enemy.alive ? 1 : clamp(enemy.squishTimer / (ENEMY_SQUISH_DURATION * 0.42), 0, 1);
623:   const bounce = enemy.alive ? Math.sin(elapsed * 8 + enemy.x * 0.2) * 1.5 : 0;
624:   const anchorY = enemy.y + enemy.h;
625: 
626:   ctx.save();
627:   ctx.globalAlpha *= fade;
628:   ctx.translate(x + enemy.w / 2, anchorY);
629:   ctx.scale(scaleX, scaleY);
630:   ctx.translate(-(x + enemy.w / 2), -anchorY);
631: 
632:   ctx.fillStyle = 'rgba(58,38,28,0.2)';
633:   ctx.beginPath();
634:   ctx.ellipse(x + enemy.w / 2, GROUND_Y - 1, 18, 4, 0, 0, Math.PI * 2);
635:   ctx.fill();
636: 
637:   const body = ctx.createRadialGradient(x + 12, enemy.y + 8 + bounce, 2, x + 17, enemy.y + 17 + bounce, 20);
638:   body.addColorStop(0, '#e7ac64');
639:   body.addColorStop(0.65, '#b77b3f');
640:   body.addColorStop(1, '#704322');
641:   ctx.fillStyle = body;
642:   ctx.beginPath();
643:   ctx.ellipse(x + enemy.w / 2, enemy.y + 19 + bounce, 18, 11, 0, 0, Math.PI * 2);
644:   ctx.fill();
645: 
646:   const cap = ctx.createLinearGradient(0, enemy.y + bounce, 0, enemy.y + 17 + bounce);
647:   cap.addColorStop(0, '#f0bd77');
648:   cap.addColorStop(0.55, '#c78a4c');
649:   cap.addColorStop(1, '#8a552e');
650:   ctx.fillStyle = cap;
651:   ctx.beginPath();
652:   ctx.arc(x + enemy.w / 2, enemy.y + 14 + bounce, 15, Math.PI, 0);
653:   ctx.fill();
654:   ctx.fillStyle = 'rgba(255,235,190,0.5)';
655:   ctx.beginPath();
656:   ctx.ellipse(x + 12, enemy.y + 6 + bounce, 5, 2, -0.25, 0, Math.PI * 2);
657:   ctx.fill();
658: 
659:   if (enemy.alive) {
660:     ctx.fillStyle = '#fff7df';
661:     ctx.fillRect(x + 9, enemy.y + 12 + bounce, 6, 8);
662:     ctx.fillRect(x + 21, enemy.y + 12 + bounce, 6, 8);
663:     ctx.fillStyle = '#30241d';
664:     ctx.fillRect(x + 12, enemy.y + 15 + bounce, 3, 4);
665:     ctx.fillRect(x + 22, enemy.y + 15 + bounce, 3, 4);
666:     ctx.fillStyle = '#fff';
667:     ctx.fillRect(x + 12, enemy.y + 15 + bounce, 1, 1);
668:     ctx.fillRect(x + 22, enemy.y + 15 + bounce, 1, 1);
669:   } else {
670:     ctx.strokeStyle = '#4b3023';
671:     ctx.lineWidth = 2;
672:     ctx.lineCap = 'round';
673:     ctx.beginPath();
674:     ctx.moveTo(x + 10, enemy.y + 17 + bounce);
675:     ctx.lineTo(x + 15, enemy.y + 16 + bounce);
676:     ctx.moveTo(x + 21, enemy.y + 16 + bounce);
677:     ctx.lineTo(x + 26, enemy.y + 17 + bounce);
678:     ctx.stroke();
679:     ctx.strokeStyle = '#704322';
680:     ctx.lineWidth = 1.5;
681:     ctx.beginPath();
682:     ctx.moveTo(x + 15, enemy.y + 22 + bounce);
683:     ctx.quadraticCurveTo(x + 18, enemy.y + 24 + bounce, x + 21, enemy.y + 22 + bounce);
684:     ctx.stroke();
685:   }
686: 
687:   roundedGradientRect(x + 3, enemy.y + 24 + bounce, 12, 5, 2, '#73513a', '#35251e');
688:   roundedGradientRect(x + 21, enemy.y + 24 + bounce, 12, 5, 2, '#73513a', '#35251e');
689:   ctx.restore();
690: }
