692: function drawPlayer() {
693:   if (!player) return;
694:   if (player.invulnerable > 0 && Math.floor(elapsed * 15) % 2) return;
695: 
696:   const x = Math.round(player.x - cameraX);
697:   const y = Math.round(player.y);
698:   const speed = Math.abs(player.vx);
699:   const moving = player.grounded && speed > 18;
700:   const runAmount = moving ? clamp(speed / 150, 0, 1) : 0;
701:   const phase = player.walk;
702:   const stride = moving ? Math.sin(phase) : 0;
703:   const bob = moving ? Math.abs(Math.sin(phase)) * 1.8 * runAmount : 0;
704:   const lean = moving ? clamp(player.vx / 285, -1, 1) * 0.12 : 0;
705:   const airborne = !player.grounded;
706:   const shadowY = Math.max(0, GROUND_Y - (y + player.h));
707: 
708:   ctx.fillStyle = `rgba(46,37,32,${Math.max(0.08, 0.2 - shadowY * 0.0007)})`;
709:   ctx.beginPath();
710:   ctx.ellipse(x + player.w / 2, y + player.h + 2, Math.max(7, 13 - shadowY * 0.06), 4, 0, 0, Math.PI * 2);
711:   ctx.fill();
712: 
713:   ctx.save();
714:   ctx.translate(x + player.w / 2, y + player.h / 2 + bob);
715:   ctx.scale(player.facing, 1);
716:   ctx.scale(1, 1 + (moving ? Math.sin(phase * 2) * 0.025 * runAmount : 0));
717:   ctx.rotate(airborne ? (player.vy < 0 ? -0.08 : 0.07) : -lean);
718: 
719:   // Arms counter-swing against the legs to make each stride feel propulsive.
720:   const armSwing = moving ? stride * 0.88 * runAmount : airborne ? -0.4 : 0.08;
721:   const drawLimb = (px, py, angle, length, width, top, bottom) => {
722:     ctx.save();
723:     ctx.translate(px, py);
724:     ctx.rotate(angle);
725:     roundedGradientRect(-width / 2, 0, width, length, width / 2, top, bottom);
726:     ctx.restore();
727:   };
728:   const drawShoe = (px, py, angle, length, width, top, bottom) => {
729:     ctx.save();
730:     ctx.translate(px, py);
731:     ctx.rotate(angle);
732:     ctx.fillStyle = bottom;
733:     ctx.beginPath();
734:     ctx.moveTo(-width * 0.55, width * 0.18);
735:     ctx.lineTo(length * 0.72, width * 0.2);
736:     ctx.quadraticCurveTo(length, width * 0.2, length * 0.88, width * 0.62);
737:     ctx.lineTo(-width * 0.52, width * 0.62);
738:     ctx.quadraticCurveTo(-width * 0.82, width * 0.46, -width * 0.55, width * 0.18);
739:     ctx.fill();
740:     ctx.fillStyle = top;
741:     ctx.beginPath();
742:     ctx.moveTo(-width * 0.62, -width * 0.28);
743:     ctx.lineTo(length * 0.58, -width * 0.48);
744:     ctx.quadraticCurveTo(length, -width * 0.42, length * 0.94, 0);
745:     ctx.lineTo(length * 0.76, width * 0.24);
746:     ctx.lineTo(-width * 0.46, width * 0.18);
747:     ctx.quadraticCurveTo(-width * 0.8, 0, -width * 0.62, -width * 0.28);
748:     ctx.fill();
749:     ctx.restore();
750:   };
751: 
752:   // Legs swing in a wide side-profile arc: one reaches forward as the other pushes back.
753:   const legSwing = moving ? Math.sin(phase) * 1.25 * runAmount : 0;
754:   const backLeg = airborne ? 0.9 : legSwing;
755:   const frontLeg = airborne ? -0.65 : -legSwing;
756:   const farLegX = -2.5 - Math.sin(phase) * 1.6 * runAmount;
757:   const nearLegX = 2.5 + Math.sin(phase) * 1.6 * runAmount;
758:   const farFootX = farLegX - Math.sin(backLeg) * 10;
759:   const farFootY = 15 + Math.cos(backLeg) * 10;
760:   const nearFootX = nearLegX - Math.sin(frontLeg) * 10;
761:   const nearFootY = 14 + Math.cos(frontLeg) * 10;
762:   drawLimb(farLegX, 13, backLeg, 10, 5, '#3983dd', '#164c9d');
763:   drawShoe(farFootX, farFootY, backLeg * 0.16, 11, 5.5, '#d58d57', '#6f3b2d');
764: 
765:   // Back arm, torso, and the forward arm are separate layers for a little depth.
766:   drawLimb(-7, -4, armSwing, 12, 5, '#f2bd91', '#bd7958');
767:   roundedGradientRect(-9, -4, 17, 19, 5, '#5fb0ff', '#174d9d');
768:   // Bring the front leg over the shirt so its forward/back swing stays readable.
769:   drawLimb(nearLegX, 12, frontLeg, 10.5, 5.5, '#55a5ff', '#1553b5');
770:   drawShoe(nearFootX, nearFootY, frontLeg * 0.16, 11, 6, '#bd6c45', '#4f2a20');
771:   ctx.fillStyle = 'rgba(215,237,255,0.58)';
772:   ctx.beginPath();
773:   ctx.moveTo(-5, -1);
774:   ctx.lineTo(-2, -2);
775:   ctx.lineTo(-2, 11);
776:   ctx.lineTo(-5, 12);
777:   ctx.closePath();
778:   ctx.fill();
779:   roundedGradientRect(0, 8, 7, 7, 2, '#f8cc4f', '#ca7b21');
780:   ctx.fillStyle = 'rgba(255,238,172,0.8)';
781:   ctx.fillRect(1, 9, 2, 3);
782:   drawLimb(6, -3, -armSwing * 0.85, 11, 6, '#ffd2a8', '#c17b58');
783: 
784:   // Profiled face: a single eye, a small forward nose, and a visible ear.
785:   const face = ctx.createLinearGradient(-7, -16, 10, 3);
786:   face.addColorStop(0, '#ffe8c2');
787:   face.addColorStop(0.68, '#f2bd8c');
788:   face.addColorStop(1, '#ce875d');
789:   ctx.fillStyle = face;
790:   ctx.beginPath();
791:   ctx.moveTo(-8, -15);
792:   ctx.quadraticCurveTo(-2, -19, 5, -15);
793:   ctx.quadraticCurveTo(9, -13, 8, -9);
794:   ctx.lineTo(12, -6);
795:   ctx.quadraticCurveTo(13, -4, 9, -3);
796:   ctx.lineTo(8, 1);
797:   ctx.quadraticCurveTo(3, 5, -5, 2);
798:   ctx.quadraticCurveTo(-10, -2, -8, -15);
799:   ctx.fill();
800: 
801:   ctx.fillStyle = '#d58c60';
802:   ctx.beginPath();
803:   ctx.ellipse(-5, -5, 2.5, 3, 0, 0, Math.PI * 2);
804:   ctx.fill();
805:   ctx.fillStyle = '#fffdf4';
806:   ctx.beginPath();
807:   ctx.ellipse(4, -10, 2.3, 3.2, -0.12, 0, Math.PI * 2);
808:   ctx.fill();
809:   ctx.fillStyle = '#30252a';
810:   ctx.beginPath();
811:   ctx.ellipse(5.2, -9.5, 1.1, 2.2, 0, 0, Math.PI * 2);
812:   ctx.fill();
813:   ctx.fillStyle = 'rgba(255,255,255,0.9)';
814:   ctx.fillRect(5, -11, 1, 1);
815:   ctx.fillStyle = '#8b423b';
816:   ctx.beginPath();
817:   ctx.moveTo(6, -1);
818:   ctx.quadraticCurveTo(8, 0, 10, -1);
819:   ctx.strokeStyle = '#8b423b';
820:   ctx.lineWidth = 1.2;
821:   ctx.stroke();
822: 
823:   // Red cap with a forward brim gives the silhouette an unmistakable direction.
824:   const cap = ctx.createLinearGradient(0, -23, 0, -11);
825:   cap.addColorStop(0, '#ff8068');
826:   cap.addColorStop(0.55, '#f04b43');
827:   cap.addColorStop(1, '#a92835');
828:   ctx.fillStyle = cap;
829:   ctx.beginPath();
830:   ctx.moveTo(-10, -16);
831:   ctx.quadraticCurveTo(-9, -23, -2, -23);
832:   ctx.lineTo(4, -22);
833:   ctx.quadraticCurveTo(7, -20, 7, -15);
834:   ctx.lineTo(12, -14);
835:   ctx.quadraticCurveTo(15, -13, 13, -11);
836:   ctx.lineTo(1, -12);
837:   ctx.lineTo(-10, -12);
838:   ctx.closePath();
839:   ctx.fill();
840:   ctx.fillStyle = 'rgba(255,220,194,0.75)';
841:   ctx.beginPath();
842:   ctx.moveTo(-7, -19);
843:   ctx.quadraticCurveTo(-2, -22, 3, -20);
844:   ctx.lineTo(3, -18);
845:   ctx.lineTo(-7, -17);
846:   ctx.closePath();
847:   ctx.fill();
848:   ctx.fillStyle = 'rgba(116,28,40,0.5)';
849:   ctx.fillRect(-8, -13, 17, 1.5);
850: 
851:   ctx.restore();
852: }
