854: function drawDecor() {
855:   const onGround = worldX => platforms.some(p => p.y === GROUND_Y && worldX >= p.x + 8 && worldX <= p.x + p.w - 8);
856: 
857:   // Short, world-anchored grass tufts break up the long platform edges without
858:   // obscuring the character's feet or the readable collision silhouette.
859:   for (let worldX = 18; worldX < LEVEL_WIDTH; worldX += 29) {
860:     if (!onGround(worldX)) continue;
861:     const x = worldX - cameraX;
862:     if (x < -12 || x > W + 12) continue;
863:     const height = 4 + (worldX % 4);
864:     ctx.strokeStyle = worldX % 2 ? '#359c4d' : '#42b752';
865:     ctx.lineWidth = 1.6;
866:     ctx.lineCap = 'round';
867:     ctx.beginPath();
868:     ctx.moveTo(x - 3, GROUND_Y - 1);
869:     ctx.lineTo(x - 4, GROUND_Y - height);
870:     ctx.moveTo(x, GROUND_Y);
871:     ctx.lineTo(x + (worldX % 3) - 1, GROUND_Y - height - 2);
872:     ctx.moveTo(x + 3, GROUND_Y - 1);
873:     ctx.lineTo(x + 5, GROUND_Y - height + 1);
874:     ctx.stroke();
875:   }
876: 
877:   // Small, varied blossoms add color at a calmer rhythm than the grass.
878:   for (let worldX = 42; worldX < LEVEL_WIDTH; worldX += 103) {
879:     if (!onGround(worldX)) continue;
880:     const x = worldX - cameraX;
881:     if (x < -12 || x > W + 12) continue;
882:     const flowerY = GROUND_Y - 9 - worldX % 3;
883:     const petal = worldX % 2 ? '#fff4d8' : '#ffd8ef';
884:     ctx.strokeStyle = '#358e48';
885:     ctx.lineWidth = 1.5;
886:     ctx.beginPath();
887:     ctx.moveTo(x, GROUND_Y - 1);
888:     ctx.lineTo(x, flowerY + 2);
889:     ctx.stroke();
890:     ctx.fillStyle = petal;
891:     for (let petalIndex = 0; petalIndex < 4; petalIndex += 1) {
892:       const angle = petalIndex * Math.PI / 2;
893:       ctx.beginPath();
894:       ctx.arc(x + Math.cos(angle) * 2.4, flowerY + Math.sin(angle) * 2.4, 1.9, 0, Math.PI * 2);
895:       ctx.fill();
896:     }
897:     ctx.fillStyle = '#ffc846';
898:     ctx.beginPath();
899:     ctx.arc(x, flowerY, 1.4, 0, Math.PI * 2);
900:     ctx.fill();
901:   }
902: }
