904: function draw() {
905:   ctx.save();
906:   if (cameraShake > 0.15) ctx.translate((Math.random() - 0.5) * cameraShake, (Math.random() - 0.5) * cameraShake);
907:   drawBackground();
908:   drawWorld();
909:   drawDecor();
910:   drawCoins();
911:   enemies.forEach(drawEnemy);
912:   drawPlayer();
913:   for (const p of particles) {
914:     ctx.globalAlpha = clamp(p.life / 0.55, 0, 1);
915:     ctx.fillStyle = p.color;
916:     const pulse = 1 + Math.sin((0.55 - p.life) * 25) * 0.6;
917:     ctx.fillRect(p.x - cameraX, p.y, p.size * pulse, p.size * pulse);
918:   }
919:   ctx.globalAlpha = 1;
920:   if (messageTimer > 0) {
921:     roundedRect(250, 22, 460, 42, 12, 'rgba(30,48,54,.85)');
922:     ctx.fillStyle = '#fff'; ctx.font = 'bold 17px system-ui'; ctx.textAlign = 'center'; ctx.fillText(message, W / 2, 49); ctx.textAlign = 'left';
923:   }
924:   // Coin progress is always visible in the playfield too.
925:   roundedRect(18, 16, 132, 38, 12, 'rgba(21,51,74,.72)');
926:   ctx.fillStyle = '#ffe16a'; ctx.font = 'bold 17px system-ui'; ctx.fillText(`● ${player ? player.coins : 0} / ${TARGET_COINS}`, 31, 41);
927:   ctx.restore();
928: }
